public static int stringCode (String value, StringBuilder encoded)
    {
        int code = 0;
        for (int ii = 0, uu = 0; ii < value.length(); ii++) {
            char c = Character.toLowerCase(value.charAt(ii));
            Integer cc = _letterToBits.get(c);
            if (cc == null) {
