public static String escapeJS(String str, char quotesUsed, CharsetEncoder enc) {
	char[] arr = str.toCharArray();
	StringBuilder rtn = new StringBuilder(arr.length);
	rtn.append(quotesUsed);

	for (int i = 0; i < arr.length; i++) {
	    switch (arr[i]) {
	    case '\\':
		rtn.append("\\\\");
		break;
	    case '\n':
		rtn.append("\\n");
		break;
	    case '\r':
		rtn.append("\\r");
		break;
	    case '\f':
		rtn.append("\\f");
		break;
	    case '\b':
		rtn.append("\\b");
		break;
	    case '\t':
		rtn.append("\\t");
		break;
	    case '"':
		if (quotesUsed == '"') rtn.append("\\\"");
		else rtn.append('"');
		break;
	    case '\'':
		if (quotesUsed == '\'') rtn.append("\\\'");
		else rtn.append('\'');
		break;
	    case '/':
		// escape </script>
		if (i > 0 && arr[i - 1] == '<' && i + 1 < arr.length && arr[i + 1] == 's' && i + 2 < arr.length && arr[i + 2] == 'c' && i + 3 < arr.length && arr[i + 3] == 'r'
			&& i + 4 < arr.length && arr[i + 4] == 'i' && i + 5 < arr.length && arr[i + 5] == 'p' && i + 6 < arr.length && arr[i + 6] == 't' && i + 7 < arr.length
			&& (isWhiteSpace(arr[i + 7]) || arr[i + 7] == '>')

		) {
		    rtn.append("\\/");
		    break;
		}

	    default:
		if (Character.isISOControl(arr[i]) || (arr[i] >= 128 && (enc == null || !enc.canEncode(arr[i])))) {
		    if (arr[i] < 0x10) rtn.append("\\u000");
		    else if (arr[i] < 0x100) rtn.append("\\u00");
		    else if (arr[i] < 0x1000) rtn.append("\\u0");
		    else rtn.append("\\u");
		    rtn.append(Integer.toHexString(arr[i]));
		}
		else {
		    rtn.append(arr[i]);
		}
		break;
	    }
	}
	return rtn.append(quotesUsed).toString();
    }

private String stringForBig(BigInteger big, int sigchars, boolean remainder)
    {
        char[] chars = new char[sigchars + (remainder ? 1 : 0)];
        if (remainder)
            // remaining bit is the most significant in the last char
            chars[sigchars] |= 0x8000;
        for (int i = 0; i < sigchars; i++)
        {
            int maskpos = 16 * (sigchars - (i + 1));
            // apply bitmask and get char value
            chars[i] = (char)(big.and(CHAR_MASK.shiftLeft(maskpos)).shiftRight(maskpos).intValue() & 0xFFFF);
        }
        return new String(chars);
    }

