						}else if(c=='b'){
							buf.append('\b');
						}else if(c=='f'){
							buf.append('\f');
						}else if(c=='n'){
							buf.append('\n');
						}else if(c=='r'){
							buf.append('\r');
						}else if(c=='t'){
							buf.append('\t');
						}else if(c=='u'){
							String code=dirtyBuf.substring(i+1,i+5);
							buf.append((char)Integer.parseInt(code, 16));
							i+=4;
						}
					}else{
						buf.append(c);
					}
				}
			}else{
				for(int i=startIndex;i<endIndex;i++){
					char c=cbuf[i];
					if(c=='\\'){
						i++;
						c=cbuf[i];
						if(c=='"' || c=='\\' || c=='/'){
