private void action(int d) throws IOException, JSMinException {
		switch (d) {
		case 1:
			write(theA);
			if ((theY == '\n' || theY == ' ') && (theA == '+' || theA == '-' || theA == '*' || theA == '/')
					&& (theB == '+' || theB == '-' || theB == '*' || theB == '/')) {
				write(theY);
			}
		case 2:
			theA = theB;
			if (theA == '\'' || theA == '"' || theA == '`') {
				for (;;) {
					write(theA);
					theA = get(true);
					if (theA == theB) {
						break;
					}
					if (theA == '\\') {
						write(theA);
						theA = get(true);
					}
					if (theA == EOF) {
						throw new UnterminatedStringLiteralException(currentByteIndex, line, column);
					}
				}
			}
		case 3:
			theB = next();
			if (theB == '/' && (theA == '(' || theA == ',' || theA == '=' || theA == ':' || theA == '[' || theA == '!'
					|| theA == '&' || theA == '|' || theA == '?' || theA == '+' || theA == '-' || theA == '~'
					|| theA == '*' || theA == '/' || theA == '{' || theA == '\n')) {
				write(theA);
				if (theA == '/' || theA == '*') {
					write(' ');
				}
				write(theB);
				for (;;) {
					theA = get();
					if (theA == '[') {
						for (;;) {
							write(theA);
							theA = get();
							if (theA == ']') {
								break;
							}
							if (theA == '\\') {
								write(theA);
								theA = get();
							}
							if (theA == EOF) {
								throw new UnterminatedRegExpLiteralException( // Unterminated
																				// set
																				// in
																				// Regular
																				// Expression
																				// literal.
										currentByteIndex, line, column);
							}
						}
					} else if (theA == '/') {
						switch (peek()) {
						case '/':
						case '*':
							throw new UnterminatedRegExpLiteralException(// Unterminated
																			// set
																			// in
																			// Regular
																			// Expression
																			// literal.
									currentByteIndex, line, column);
						}
						break;
					} else if (theA == '\\') {
						write(theA);
						theA = get();
					}
					if (theA == EOF) {
						throw new UnterminatedRegExpLiteralException(currentByteIndex, line, column);
					}
					write(theA);
				}
				theB = next();
			}
		}
	}

