      pointEnd2 = nextRelationClass.getPointJoint();      
    }
    else {//from this to interJoint
      pointEnd2 = new Point2D(relClrel.getRelationship().getSharedJoint().getX(), 
          relClrel.getRelationship().getSharedJoint().getY());
    }
    Point2D pointEnd1 = new Point2D(relClrel.getClassRelationship().getPointJoint().getX(), relClrel.getClassRelationship().getPointJoint().getY());
    if(relClrel.getClassRelationship().getSideJoint() == EJointSide.BOTTOM || relClrel.getClassRelationship().getSideJoint() == EJointSide.TOP) {
      pointEnd1.setX(pointEnd2.getX());
    }
    else {
      pointEnd1.setY(pointEnd2.getY());
    }
    return new Point2D[]{relClrel.getClassRelationship().getPointJoint(), pointEnd1, pointEnd2};
  }

@SuppressWarnings({"ConstantConditions", "deprecation"})
    @SuppressFBWarnings("RCN_REDUNDANT_NULLCHECK_OF_NONNULL_VALUE")
    public boolean replaceActions(@Nonnull Class<? extends Action> clazz, @Nonnull Action a) {
        if (clazz == null) {
            throw new IllegalArgumentException("Action type must be non-null");
        }
        if (a == null) {
            throw new IllegalArgumentException("Action must be non-null");
        }
        // CopyOnWriteArrayList does not support Iterator.remove, so need to do it this way:
        List<Action> old = new ArrayList<>();
        List<Action> current = getActions();
        boolean found = false;
        for (Action a1 : current) {
            if (!found) {
                if (a.equals(a1)) {
                    found = true;
                } else if (clazz.isInstance(a1)) {
                    old.add(a1);
                }
            } else if (clazz.isInstance(a1) && !a.equals(a1)) {
                old.add(a1);
            }
        }
        current.removeAll(old);
        if (!found) {
            addAction(a);
        }
        return !(old.isEmpty() && found);
    }

private void repartitionSplitState(
			Map<String, List<Tuple2<StreamStateHandle, OperatorStateHandle.StateMetaInfo>>> nameToDistributeState,
			int newParallelism,
			List<Map<StreamStateHandle, OperatorStateHandle>> mergeMapList) {

		int startParallelOp = 0;
		// Iterate all named states and repartition one named state at a time per iteration
		for (Map.Entry<String, List<Tuple2<StreamStateHandle, OperatorStateHandle.StateMetaInfo>>> e :
				nameToDistributeState.entrySet()) {

			List<Tuple2<StreamStateHandle, OperatorStateHandle.StateMetaInfo>> current = e.getValue();

			// Determine actual number of partitions for this named state
			int totalPartitions = 0;
			for (Tuple2<StreamStateHandle, OperatorStateHandle.StateMetaInfo> offsets : current) {
				totalPartitions += offsets.f1.getOffsets().length;
			}

			// Repartition the state across the parallel operator instances
			int lstIdx = 0;
			int offsetIdx = 0;
			int baseFraction = totalPartitions / newParallelism;
			int remainder = totalPartitions % newParallelism;

			int newStartParallelOp = startParallelOp;

			for (int i = 0; i < newParallelism; ++i) {

				// Preparation: calculate the actual index considering wrap around
				int parallelOpIdx = (i + startParallelOp) % newParallelism;

				// Now calculate the number of partitions we will assign to the parallel instance in this round ...
				int numberOfPartitionsToAssign = baseFraction;

				// ... and distribute odd partitions while we still have some, one at a time
				if (remainder > 0) {
					++numberOfPartitionsToAssign;
					--remainder;
				} else if (remainder == 0) {
					// We are out of odd partitions now and begin our next redistribution round with the current
					// parallel operator to ensure fair load balance
					newStartParallelOp = parallelOpIdx;
					--remainder;
				}

				// Now start collection the partitions for the parallel instance into this list

				while (numberOfPartitionsToAssign > 0) {
					Tuple2<StreamStateHandle, OperatorStateHandle.StateMetaInfo> handleWithOffsets =
							current.get(lstIdx);

					long[] offsets = handleWithOffsets.f1.getOffsets();
					int remaining = offsets.length - offsetIdx;
					// Repartition offsets
					long[] offs;
					if (remaining > numberOfPartitionsToAssign) {
						offs = Arrays.copyOfRange(offsets, offsetIdx, offsetIdx + numberOfPartitionsToAssign);
						offsetIdx += numberOfPartitionsToAssign;
					} else {
						if (OPTIMIZE_MEMORY_USE) {
							handleWithOffsets.f1 = null; // GC
						}
						offs = Arrays.copyOfRange(offsets, offsetIdx, offsets.length);
						offsetIdx = 0;
						++lstIdx;
					}

					numberOfPartitionsToAssign -= remaining;

					// As a last step we merge partitions that use the same StreamStateHandle in a single
					// OperatorStateHandle
					Map<StreamStateHandle, OperatorStateHandle> mergeMap = mergeMapList.get(parallelOpIdx);
					OperatorStateHandle operatorStateHandle = mergeMap.get(handleWithOffsets.f0);
					if (operatorStateHandle == null) {
						operatorStateHandle = new OperatorStreamStateHandle(
							new HashMap<>(nameToDistributeState.size()),
							handleWithOffsets.f0);
						mergeMap.put(handleWithOffsets.f0, operatorStateHandle);
					}
					operatorStateHandle.getStateNameToPartitionOffsets().put(
							e.getKey(),
							new OperatorStateHandle.StateMetaInfo(offs, OperatorStateHandle.Mode.SPLIT_DISTRIBUTE));
				}
			}
			startParallelOp = newStartParallelOp;
			e.setValue(null);
		}
	}

public static int execute(String[] commandArray, String[] alternativeEnvVars, File workingDir, Receiver outputReceiver) throws IOException {
		Runtime rt = Runtime.getRuntime();
		//command + arguments, environment parameters, workingdir
        Process proc = null;
        try {
		    proc = rt.exec(commandArray, alternativeEnvVars, workingDir);
        } catch (Exception e) {
            System.out.println("unable to execute command: " + ArraySupport.format(commandArray, ", "));
            e.printStackTrace();
            throw new RuntimeException("unable to execute command: " + ArraySupport.format(commandArray, ", "), e);
        }

		// any error message?
		Transponder errorForwarder = new
				Transponder(proc.getErrorStream(), new Pipe(outputReceiver));

		// any output?
		Transponder outputForwarder = new
				Transponder(proc.getInputStream(), new Pipe(outputReceiver));

		errorForwarder.start();
		outputForwarder.start();

		try {
			int retval = proc.waitFor();//threads will stop when proc is done and InputStream and ErrorStream close
			errorForwarder.stop();
			outputForwarder.stop();
			return retval;
		}
		catch (InterruptedException ie) {
			//...
		}
		return -1;
	}

public static void runExample(
      AdManagerServices adManagerServices, AdManagerSession session, int activityId)
      throws RemoteException {
    // Get the ActivityService.
    ActivityServiceInterface activityService =
        adManagerServices.get(session, ActivityServiceInterface.class);

    // Create a statement to only select a single activity by ID.
    StatementBuilder statementBuilder =
        new StatementBuilder()
            .where("id = :id")
            .orderBy("id ASC")
            .limit(1)
            .withBindVariableValue("id", activityId);

    // Get the activity.
    ActivityPage page = activityService.getActivitiesByStatement(statementBuilder.toStatement());

    // Get the activity.
    Activity activity = Iterables.getOnlyElement(Arrays.asList(page.getResults()));

    // Update the expected URL.
    activity.setExpectedURL("http://google.com");

    // Update the activity on the server.
    Activity[] activities = activityService.updateActivities(new Activity[] {activity});

    for (Activity updatedActivity : activities) {
      System.out.printf(
          "Activity with ID %d and name '%s' was updated.%n",
          updatedActivity.getId(), updatedActivity.getName());
    }
  }

