protected X509Certificate wireUpSslWithCyberVilliansCAOdo(String host, SslListener listener) {
        host = requestOriginalHostName.get();

        // Add cybervillians CA(from browsermob)
        try {
            // see https://github.com/webmetrics/browsermob-proxy/issues/105
            String escapedHost = host.replace('*', '_');

            KeyStoreManager keyStoreManager = Utils.getKeyStoreManager(escapedHost);
            keyStoreManager.getKeyStore().deleteEntry(KeyStoreManager._caPrivKeyAlias);
            keyStoreManager.persist();
            listener.setKeystore(new File("seleniumSslSupport" + File.separator + escapedHost + File.separator + "cybervillainsCA.jks").getAbsolutePath());

            return keyStoreManager.getCertificateByAlias(escapedHost);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

@Override
  public void export(Collection<SpanData> spanDataList) {
    Scope scope =
        tracer
            .spanBuilder("ExportElasticsearchTraces")
            .setSampler(probabilitySampler)
            .setRecordEvents(true)
            .startScopedSpan();
    try {
      List<String> jsonList = JsonConversionUtils.convertToJson(appName, spanDataList);
      if (jsonList.isEmpty()) {
        return;
      }
      for (String json : jsonList) {

        OutputStream outputStream = null;
        InputStream inputStream = null;

        try {
          HttpURLConnection connection = (HttpURLConnection) indexUrl.openConnection();
          if (elasticsearchTraceConfiguration.getUserName() != null) {
            String parameters =
                BaseEncoding.base64()
                    .encode(
                        (elasticsearchTraceConfiguration.getUserName()
                                + ":"
                                + elasticsearchTraceConfiguration.getPassword())
                            .getBytes("UTF-8"));
            connection.setRequestProperty("Authorization", "Basic " + parameters);
          }
          connection.setRequestMethod(REQUEST_METHOD);
          connection.setDoOutput(true);
          connection.setConnectTimeout(CONNECTION_TIMEOUT_MILLISECONDS);
          connection.setRequestProperty("Content-Type", CONTENT_TYPE);
          outputStream = connection.getOutputStream();
          outputStream.write(json.getBytes(Charset.defaultCharset()));
          outputStream.flush();
          inputStream = connection.getInputStream();
          if (connection.getResponseCode() != 200) {
            tracer
                .getCurrentSpan()
                .setStatus(
                    Status.UNKNOWN.withDescription("Response " + connection.getResponseCode()));
          }
        } catch (IOException e) {
          tracer
              .getCurrentSpan()
              .setStatus(
                  Status.UNKNOWN.withDescription(
                      e.getMessage() == null ? e.getClass().getSimpleName() : e.getMessage()));
          // dropping span batch
        } finally {
          if (inputStream != null) {
            try {
              inputStream.close();
            } catch (IOException e) {
              // ignore
            }
          }
          if (outputStream != null) {
            try {
              outputStream.close();
            } catch (IOException e) {
              // ignore
            }
          }
        }
      }
    } finally {
      scope.close();
    }
  }

public java.lang.String getMessage() {
        if (resourceBundleName != null && resourceKey != null) {
            String retrievedMessage = null;
            String internalMessage = null;
            String defaultEnglishMessage = null;
            ResourceBundle bundle = null;

            // retrieve the resource bundle
            try {
                bundle = ResourceBundle.getBundle(resourceBundleName);
            } catch (MissingResourceException e) {
                String key = null;
                if (message == null) {
                    key = "missingResourceBundleNoDft";
                    defaultEnglishMessage = "There was an error retrieving resource bundle {0}. \nThere is no default message.";
                } else {
                    key = "missingResourceBundleWithDft";
                    defaultEnglishMessage = "There was an error retrieving resource bundle {0}. \nThe default exception message is: {2}.";
                }

                internalMessage = getErrorMsg(DIST_EX_RESOURCE_BUNDLE_NAME, key, defaultEnglishMessage);
            }

            // if the resource bundle was successfully retrieved, get the specific message based
            // on the resource key
            if (bundle != null) {
                try {
                    retrievedMessage = bundle.getString(resourceKey);
                } catch (MissingResourceException e) {
                    String key = null;
                    if (message == null) {
                        key = "missingResourceKeyNoDft";
                        defaultEnglishMessage = "There was an error retrieving resource key {1} in resource bundle {0}. \nThere is no default message.";
                    } else {
                        key = "missingResourceKeyWithDft";
                        defaultEnglishMessage = "There was an error retrieving resource key {1} in resource bundle {0}. \nThe default exception message is: {2}.";
                    }

                    internalMessage = getErrorMsg(DIST_EX_RESOURCE_BUNDLE_NAME, key, defaultEnglishMessage);
                }

            }

            String formattedMessage = null;

            // format the message
            if (retrievedMessage != null) {
                if (formatArguments != null) {
                    formattedMessage = MessageFormat.format(retrievedMessage, formatArguments);
                } else {
                    formattedMessage = retrievedMessage;
                }

            } else if (internalMessage != null) {
                Object intFormatArguments[] = { resourceBundleName, resourceKey, message };
                formattedMessage = MessageFormat.format(internalMessage, intFormatArguments);
            } else { // shouldn't happen
                return message; // which could be null
            }

            return formattedMessage;
        } else { // resource information does not exist, so return the default message, if provided
            return message;
        }
    }

