public static String formatAsStackTraceElement(InjectionPoint ij) {
        Member member;
        if (ij.getAnnotated() instanceof AnnotatedField) {
            AnnotatedField<?> annotatedField = (AnnotatedField<?>) ij.getAnnotated();
            member = annotatedField.getJavaMember();
        } else if (ij.getAnnotated() instanceof AnnotatedParameter<?>) {
            AnnotatedParameter<?> annotatedParameter = (AnnotatedParameter<?>) ij.getAnnotated();
            member = annotatedParameter.getDeclaringCallable().getJavaMember();
        } else {
            // Not throwing an exception, because this method is invoked when an exception is already being thrown.
            // Throwing an exception here would hide the original exception.
            return "-";
        }
        return formatAsStackTraceElement(member);
    }

private List<LdapEntry> deleteAll(LdapEntry ldapEntry, boolean delDescendant) throws WIMException {
        String dn = ldapEntry.getDN();
        List<LdapEntry> delEntries = new ArrayList<LdapEntry>();
        List<LdapEntry> descs = getDescendants(dn, SearchControls.ONELEVEL_SCOPE);
        if (descs.size() > 0) {
            if (delDescendant) {
                for (int i = 0; i < descs.size(); i++) {
                    LdapEntry descEntry = descs.get(i);
                    delEntries.addAll(deleteAll(descEntry, true));
                }
            } else {
                throw new EntityHasDescendantsException(WIMMessageKey.ENTITY_HAS_DESCENDENTS, Tr.formatMessage(tc, WIMMessageKey.ENTITY_HAS_DESCENDENTS,
                                                                                                               WIMMessageHelper.generateMsgParms(dn)));
            }
        }

        /* Call the preexit function */
        deletePreExit(dn);

        List<String> grpList = getGroups(dn);
        iLdapConn.getContextManager().destroySubcontext(dn);
        delEntries.add(ldapEntry);
        for (int i = 0; i < grpList.size(); i++) {
            String grpDN = grpList.get(i);
            iLdapConn.invalidateAttributes(grpDN, null, null);
        }
        return delEntries;
    }

