                type = DBConstants.DATE_TIME_FORMAT;
        } catch (ParseException e) {
        }

        try {
            if (parsedDate == null)
            {
                parsedDate = XmlUtilities.dateFormat.parse(strValue);
                type = DBConstants.DATE_ONLY_FORMAT;
            }
        } catch (ParseException e) {
        }

        try {
